-- Past-paper PDF links (question paper + mark scheme) sourced from
-- PhysicsAndMathsTutor and HEAD-verified to return application/pdf.
--
-- The archive previously shipped only the board's landing page (source_url), so
-- every card read "Not in our library yet". These are direct, verified PDF URLs
-- for the rows PMT carries.
--
-- Scope: Cambridge IGCSE 0478/0580/0625 and AS/A2 9618; Edexcel IAL Maths
-- (WMA11/12/13, WME01, WST01/02) and Physics (WPH11-15).
-- Rows omitted here (2020 June sittings cancelled; 2025 Nov not yet published)
-- keep their source_url destination.
--
-- coalesce() means a real uploaded watermarked file, if one exists, is never
-- overwritten.

update public.past_papers pp
set paper_url = coalesce(pp.paper_url, v.paper_url),
    mark_scheme_url = coalesce(pp.mark_scheme_url, v.mark_scheme_url),
    updated_at = now()
